mapper.select:
SELECT 
  FROM OBSTACLE_REPORTS
 WHERE ID        = #{id}
   AND REGION_ID = #{regionId}

mapper.update:
UPDATE OBSTACLE_REPORTS
   SET LATITUDE       = #{latitude}
     , LONGITUDE      = #{longitude}
     , BLOCK_RADIUS_M = #{blockRadiusM}
 WHERE ID        = #{id}
   AND REGION_ID = #{regionId}

UPDATE OBSTACLE_REPORTS
   SET STATUS      = #{status}
     , VERIFIED_BY = #{verifiedBy}
     , VERIFIED_AT = NOW()
 WHERE ID        = #{id}
   AND REGION_ID = #{regionId}
